{
  "prompt": "Branch add-archived-flag is ready for review, and BRANCH.md lists its commits. Write its pull request description into PR.md.",
  "kind": "task",
  "expectations": [
    {
      "text": "The description is in PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "Changes are listed by area",
      "source": "format",
      "judged": {
        "question": "Under What changed, does the description have one bullet per area of the code, not one per commit?",
        "pass": "Yes when the migration and the endpoint each get a bullet.",
        "fail": "No when PR.md repeats the two commit subjects.",
        "examples": {
          "pass": [
            "Database: new column. API: archived orders left out."
          ],
          "fail": [
            "- Add an archived column to orders\n- Leave archived orders out of the list endpoint"
          ]
        }
      }
    },
    {
      "text": "Risk names the stored data",
      "source": "format",
      "judged": {
        "question": "Under Risk, does it name anything that touches stored data, logins or the public API, or say Low when nothing does?",
        "pass": "Yes when Risk names the migration on the orders table.",
        "fail": "No when Risk says Low, or there is no Risk.",
        "examples": {
          "pass": [
            "Risk: migration 0007 changes the orders table."
          ],
          "fail": [
            "Risk: Low."
          ]
        }
      }
    },
    {
      "text": "How to test is exact",
      "source": "format",
      "judged": {
        "question": "Under How to test, does it list the exact commands to run and what passing looks like?",
        "pass": "Yes when a command comes with its expected result.",
        "fail": "No when there is no command, or no result.",
        "examples": {
          "pass": [
            "`python3 -m unittest`, which ends with OK."
          ],
          "fail": [
            "Run the tests."
          ]
        }
      }
    }
  ]
}

