{
  "prompt": "Branch fix-setup-typos only touches the setup guide, and BRANCH.md lists its commits. Write its pull request description into PR.md.",
  "kind": "task",
  "expectations": [
    {
      "text": "The description is in PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "It opens with the problem",
      "source": "format",
      "judged": {
        "question": "Does it open with a sentence or two on the problem the change solves, in words a user would use?",
        "pass": "Yes when the first lines say the setup guide had typos.",
        "fail": "No when it opens with file names.",
        "examples": {
          "pass": [
            "The setup guide had typos that confused new staff."
          ],
          "fail": [
            "docs/setup.md: 4 lines changed."
          ]
        }
      }
    },
    {
      "text": "It is short",
      "source": "format",
      "judged": {
        "question": "Does it drop anything that only repeats the diff and stay under 300 words?",
        "pass": "Yes when PR.md is under 300 words and lists no diff lines.",
        "fail": "No when it is longer or pastes the diff.",
        "examples": {
          "pass": [
            "A PR.md of 70 words."
          ],
          "fail": [
            "A PR.md that pastes every changed line."
          ]
        }
      }
    }
  ]
}

